PRAGMA foreign_keys=ON;
CREATE TABLE usuarios(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,senha_hash TEXT NOT NULL,perfil TEXT NOT NULL DEFAULT 'CLIENTE' CHECK(perfil IN('CLIENTE','OPERADOR','ADMIN')),ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessoes(id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expira_em TEXT NOT NULL,revogado_em TEXT,ip TEXT,user_agent TEXT,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE lojas(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE COLLATE NOCASE,endereco TEXT,cidade TEXT DEFAULT 'Barra do Garças',estado TEXT DEFAULT 'MT',ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categorias(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE COLLATE NOCASE,ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE produtos(id INTEGER PRIMARY KEY AUTOINCREMENT,loja_id INTEGER NOT NULL,categoria_id INTEGER NOT NULL,nome TEXT NOT NULL,descricao TEXT,preco REAL NOT NULL CHECK(preco>=0),estoque INTEGER NOT NULL DEFAULT 0 CHECK(estoque>=0),status TEXT NOT NULL DEFAULT 'ATIVO' CHECK(status IN('ATIVO','INATIVO')),destaque INTEGER NOT NULL DEFAULT 0 CHECK(destaque IN(0,1)),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(loja_id) REFERENCES lojas(id) ON DELETE RESTRICT,FOREIGN KEY(categoria_id) REFERENCES categorias(id) ON DELETE RESTRICT);
CREATE TABLE produto_imagens(id INTEGER PRIMARY KEY AUTOINCREMENT,produto_id INTEGER NOT NULL,url TEXT NOT NULL,alt_text TEXT,principal INTEGER NOT NULL DEFAULT 0 CHECK(principal IN(0,1)),ordem INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(produto_id) REFERENCES produtos(id) ON DELETE CASCADE);
CREATE TABLE auditoria(id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER,acao TEXT NOT NULL,entidade TEXT NOT NULL,entidade_id INTEGER,detalhes TEXT,ip TEXT,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE INDEX idx_usuarios_email ON usuarios(email);
CREATE INDEX idx_sessoes_token ON sessoes(token_hash);
CREATE INDEX idx_sessoes_expira ON sessoes(expira_em);
CREATE INDEX idx_produtos_loja ON produtos(loja_id);
CREATE INDEX idx_produtos_categoria ON produtos(categoria_id);
CREATE INDEX idx_produtos_status ON produtos(status);
CREATE INDEX idx_produtos_nome ON produtos(nome);
CREATE INDEX idx_imagens_produto ON produto_imagens(produto_id);
CREATE INDEX idx_auditoria_entidade ON auditoria(entidade,entidade_id);
